-- [MINOR] metric view cession_metrics redefined (views are stateless)
CREATE OR REPLACE VIEW lr_serverless_aws_us_catalog.bricksurance_semantics.cession_metrics
COMMENT 'Outward reinsurance KPIs over the cession bordereau: gross and ceded premium by treaty and period. Amounts are in original transaction currency; group by or filter on currency_code before summing money. Query measures with MEASURE(name).'
WITH METRICS
LANGUAGE YAML
AS $$
version: 0.1

source: lr_serverless_aws_us_catalog.bricksurance_exchange.cession_bordereau_line

joins:
  - name: line_of_business
    source: lr_serverless_aws_us_catalog.bricksurance_reference.line_of_business
    on: source.line_of_business_code = line_of_business.line_of_business_code

dimensions:
  - name: treaty_reference
    expr: treaty_reference
  - name: reporting_month
    expr: reporting_month
  - name: line_of_business
    expr: line_of_business.label
  - name: line_of_business_code
    expr: source.line_of_business_code
  - name: currency_code
    expr: currency_code

measures:
  - name: gross_premium
    expr: SUM(gross_premium)
  - name: ceded_premium
    expr: SUM(ceded_premium)
  - name: average_ceded_share
    expr: SUM(ceded_premium) / NULLIF(SUM(gross_premium), 0)
  - name: ceded_policy_count
    expr: COUNT(DISTINCT policy_number)
$$;

-- [MINOR] metric view submission_metrics redefined (views are stateless)
CREATE OR REPLACE VIEW lr_serverless_aws_us_catalog.bricksurance_semantics.submission_metrics
COMMENT 'Reinsurance submission funnel KPIs: volumes and requested capacity by status, form and year. Amounts are in original submission currency; group by or filter on currency_code before summing money. Query measures with MEASURE(name).'
WITH METRICS
LANGUAGE YAML
AS $$
version: 0.1

source: lr_serverless_aws_us_catalog.bricksurance_reinsurance.submission

joins:
  - name: submission_status
    source: lr_serverless_aws_us_catalog.bricksurance_reference.submission_status
    on: source.submission_status_code = submission_status.submission_status_code
  - name: line_of_business
    source: lr_serverless_aws_us_catalog.bricksurance_reference.line_of_business
    on: source.line_of_business_code = line_of_business.line_of_business_code

dimensions:
  - name: underwriting_year
    expr: underwriting_year
  - name: submission_status
    expr: submission_status.label
  - name: treaty_type_code
    expr: treaty_type_code
  - name: line_of_business
    expr: line_of_business.label
  - name: line_of_business_code
    expr: source.line_of_business_code
  - name: currency_code
    expr: currency_code

measures:
  - name: submission_count
    expr: COUNT(DISTINCT submission_id)
  - name: bound_count
    expr: COUNT(DISTINCT CASE WHEN submission_status_code = 'BOUND' THEN submission_id END)
  - name: bind_ratio
    expr: COUNT(DISTINCT CASE WHEN submission_status_code = 'BOUND' THEN submission_id END) / NULLIF(COUNT(DISTINCT submission_id), 0)
  - name: requested_limit_total
    expr: SUM(requested_limit)
$$;

-- [MINOR] metric view valuation_metrics redefined (views are stateless)
CREATE OR REPLACE VIEW lr_serverless_aws_us_catalog.bricksurance_semantics.valuation_metrics
COMMENT 'Published valuation figures (BEL, technical provisions, SCR, CSM...) by run, measure and line of business - one semantic surface across life and non-life, Solvency II and IFRS 17. Amounts are in original currency; group by or filter on currency_code and valuation_measure_code before summing. Query measures with MEASURE(name).'
WITH METRICS
LANGUAGE YAML
AS $$
version: 0.1

source: lr_serverless_aws_us_catalog.bricksurance_finance.valuation_result

joins:
  - name: valuation_run
    source: lr_serverless_aws_us_catalog.bricksurance_life.valuation_run
    on: source.valuation_run_id = valuation_run.valuation_run_id
  - name: line_of_business
    source: lr_serverless_aws_us_catalog.bricksurance_reference.line_of_business
    on: source.line_of_business_code = line_of_business.line_of_business_code

dimensions:
  - name: valuation_date
    expr: valuation_run.valuation_date
  - name: valuation_measure_code
    expr: valuation_measure_code
  - name: line_of_business
    expr: line_of_business.label
  - name: line_of_business_code
    expr: source.line_of_business_code
  - name: cohort
    expr: cohort
  - name: currency_code
    expr: currency_code

measures:
  - name: total_amount
    expr: SUM(amount)
  - name: run_count
    expr: COUNT(DISTINCT valuation_run_id)
$$;

